from statsmodels.tsa.arima.model import ARIMA

def fit_ar1_arima(x):
    res = ARIMA(x, order=(1, 0, 0)).fit()
    mu, phi, sigma2 = res.params
    return round(float(mu), 3), round(float(phi), 3), round(float(sigma2), 3)
